function puedeEditar()       { return ['romero', 'admin', 'guillermo'].includes(userActual); }

function simboloMoneda(moneda) {
  return moneda === 'USD' ? 'US$' : '$';
}

function formatearMonto(moneda, valor) {
  const num = parseFloat(valor) || 0;
  return simboloMoneda(moneda) + ' ' + num.toLocaleString('es-AR', { minimumFractionDigits: 2, maximumFractionDigits: 2 });
}

/* ── Monto en letras (español, hasta millones + céntimos) ── */
function montoEnLetras(n) {
  const UNIDADES = ['', 'un', 'dos', 'tres', 'cuatro', 'cinco', 'seis', 'siete', 'ocho', 'nueve',
    'diez', 'once', 'doce', 'trece', 'catorce', 'quince', 'dieciséis', 'diecisiete', 'dieciocho', 'diecinueve'];
  const DECENAS = ['', '', 'veinte', 'treinta', 'cuarenta', 'cincuenta', 'sesenta', 'setenta', 'ochenta', 'noventa'];
  const CENTENAS = ['', 'ciento', 'doscientos', 'trescientos', 'cuatrocientos', 'quinientos',
    'seiscientos', 'setecientos', 'ochocientos', 'novecientos'];

  function trescientos(num) {
    if (num === 0) return '';
    if (num === 100) return 'cien';
    let s = '';
    const c = Math.floor(num / 100);
    const resto = num % 100;
    if (c > 0) s += CENTENAS[c] + ' ';
    if (resto > 0) {
      if (resto < 20) {
        s += UNIDADES[resto];
      } else {
        const d = Math.floor(resto / 10);
        const u = resto % 10;
        if (resto < 30) {
          s += 'veinti' + UNIDADES[u];
        } else {
          s += DECENAS[d] + (u > 0 ? ' y ' + UNIDADES[u] : '');
        }
      }
    }
    return s.trim();
  }

  function seccion(num, singular, plural) {
    if (num === 0) return '';
    if (num === 1) return (singular === 'mil' ? 'mil' : 'un ' + singular);
    return trescientos(num) + ' ' + plural;
  }

  function entero(num) {
    if (num === 0) return 'cero';
    num = Math.floor(num);
    const millones  = Math.floor(num / 1000000);
    const miles     = Math.floor((num % 1000000) / 1000);
    const cientos   = num % 1000;
    let partes = [];
    if (millones > 0) partes.push(seccion(millones, 'millón', 'millones'));
    if (miles > 0)    partes.push(seccion(miles, 'mil', 'mil'));
    if (cientos > 0)  partes.push(trescientos(cientos));
    return partes.filter(Boolean).join(' ').trim();
  }

  const num = parseFloat(n) || 0;
  const parteEntera    = Math.floor(num);
  const centavos       = Math.round((num - parteEntera) * 100);
  const centavosTexto  = String(centavos).padStart(2, '0');
  const enteroTexto    = entero(parteEntera);
  return `${enteroTexto.charAt(0).toUpperCase() + enteroTexto.slice(1)} con ${centavosTexto}/100`;
}

function proyBadge(r) {
  if (!r.Proyecto) return '';
  return `<span class="proyecto-badge proyecto-${r.Proyecto.toLowerCase()}">${r.Proyecto}</span>`;
}

function metBadge(r) {
  if (r.Metodologia !== 'personalizado') return '';
  return `<span class="metodologia-badge">Personalizado</span>`;
}

function metaRegistro(r, incluirFecha) {
  const prefFecha = incluirFecha ? `${r.Fecha} · ` : '';
  if (r.Metodologia === 'personalizado') {
    const presu = parseFloat(r.PresupuestoTotal) || 0;
    const avz   = parseFloat(r.Total) || 0;
    const pct   = presu > 0 ? Math.min(100, Math.round((avz / presu) * 100)) : 0;
    const pago = pagoPersonalizadoInfo(r);
    const pagoTxt = pago.estado === 'anticipo' ? ` · Pago: Anticipo ${pago.porcentaje}%` : ` · Pago: ${pago.label}`;
    return `${prefFecha}Avanzado ${formatearMonto(r.Moneda || 'ARS', avz)} de ${formatearMonto(r.Moneda || 'ARS', presu)} (${pct}%)${pagoTxt}`;
  }
  return `${prefFecha}${r.Estado} · Cant: ${r.Cantidad}${r.Factura ? ' · Fac: ' + r.Factura : ''}${r.Codigo ? ' · Cód: ' + r.Codigo : ''}`;
}

function adjuntoLinkHTML(r) {
  if (!r.AdjuntoURL) return '';
  const pdf = r.AdjuntoTipo === 'application/pdf' || (r.AdjuntoNombre || '').toLowerCase().endsWith('.pdf');
  if (pdf) {
    return `<a href="${r.AdjuntoURL}" target="_blank" class="adjunto-link adjunto-pdf" onclick="event.stopPropagation()">
      <svg xmlns="http://www.w3.org/2000/svg" width="13" height="13" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round">
        <path d="M14 2H6a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V8z"/>
        <polyline points="14 2 14 8 20 8"/>
      </svg>PDF</a>`;
  }
  return `<a href="${r.AdjuntoURL}" target="_blank" class="adjunto-link adjunto-img" onclick="event.stopPropagation()">
      <svg xmlns="http://www.w3.org/2000/svg" width="13" height="13" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round">
        <rect x="3" y="3" width="18" height="18" rx="2" ry="2"/>
        <circle cx="8.5" cy="8.5" r="1.5"/>
        <polyline points="21 15 16 10 5 21"/>
      </svg>Foto</a>`;
}

