/* ════════════════════════════════════════════════════════
   HISTORIAL
   ════════════════════════════════════════════════════════ */
function filtrarHistorial(tipo) {
  historialTipoFiltro = tipo;
  if (tipo !== 'personalizado') historialTrabajoFiltro = 'todos';

  document.querySelectorAll('[data-hist-filtro]').forEach(b =>
    b.classList.toggle('active', b.dataset.histFiltro === tipo)
  );
  const estados = document.getElementById('historialPersonalizadoEstados');
  const leyenda = document.getElementById('leyendaHistorialEstados');
  if (estados) estados.classList.toggle('hidden', tipo !== 'personalizado');
  if (leyenda) {
    leyenda.innerHTML = tipo === 'personalizado'
      ? '<span class="leyenda-item" style="background:#fcebeb;color:#791f1f;">● Sin iniciar</span><span class="leyenda-item" style="background:#e4f2f8;color:#1a6080;">● Iniciado</span><span class="leyenda-item" style="background:#faeeda;color:#854f0b;">● Pausado</span><span class="leyenda-item" style="background:#eaf3de;color:#27500a;">● Finalizado</span>'
      : '<span class="leyenda-item" style="background:#fcebeb;color:#791f1f;">● Pendiente</span><span class="leyenda-item" style="background:#faeeda;color:#854f0b;">● Habilitado</span><span class="leyenda-item" style="background:#eaf3de;color:#27500a;">● Pagado</span>';
  }
  renderHistorial();
}

function filtrarEstadoTrabajo(estado) {
  historialTrabajoFiltro = estado;
  document.querySelectorAll('[data-trabajo-filtro]').forEach(b =>
    b.classList.toggle('active', b.dataset.trabajoFiltro === estado)
  );
  renderHistorial();
}

function cambiarEstadoTrabajo(firestoreId, nuevoEstado) {
  if (!puedeEditar()) return;
  const permitidos = ['sin_iniciar', 'iniciado', 'pausado', 'finalizado'];
  if (!permitidos.includes(nuevoEstado)) return;
  db.collection(COL).doc(firestoreId).update({ EstadoTrabajo: nuevoEstado })
    .catch(e => alert('Error al actualizar el estado del trabajo: ' + e.message));
}

function actualizarFiltroMesHistorial() {
  const select = document.getElementById('historialMes');
  if (!select) return;
  const meses = [...new Set(inventario.map(r => {
    const ts = Number(r.timestamp);
    if (!Number.isNaN(ts) && ts > 0) {
      const d = new Date(ts);
      return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}`;
    }
    const m = String(r.Fecha || '').match(/^(\d{1,2})[\/-](\d{1,2})[\/-](\d{4})$/);
    return m ? `${m[3]}-${String(m[2]).padStart(2,'0')}` : null;
  }).filter(Boolean))].sort().reverse();

  const actual = historialMesFiltro;
  select.innerHTML = '<option value="todos">Todos los meses</option>' + meses.map(key => {
    const [y,m] = key.split('-');
    const nombre = new Date(Number(y), Number(m)-1, 1).toLocaleDateString('es-AR', {month:'long', year:'numeric'});
    return `<option value="${key}">${nombre.charAt(0).toUpperCase()+nombre.slice(1)}</option>`;
  }).join('');
  select.value = meses.includes(actual) || actual === 'todos' ? actual : 'todos';
  if (select.value !== actual) historialMesFiltro = 'todos';
}

function claveMesRegistro(r) {
  const ts = Number(r.timestamp);
  if (!Number.isNaN(ts) && ts > 0) {
    const d = new Date(ts);
    return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}`;
  }
  const m = String(r.Fecha || '').match(/^(\d{1,2})[\/-](\d{1,2})[\/-](\d{4})$/);
  return m ? `${m[3]}-${String(m[2]).padStart(2,'0')}` : '';
}

function filtrarHistorialMes(mes) {
  historialMesFiltro = mes || 'todos';
  renderHistorial();
}

function renderHistorial() {
  const lista = document.getElementById('historialList');
  if (!lista) return;
  actualizarFiltroMesHistorial();

  // Guillermo debe poder consultar todo el historial, no solamente sus propios registros.
  let items = [...inventario].reverse();

  if (historialMesFiltro !== 'todos') items = items.filter(r => claveMesRegistro(r) === historialMesFiltro);
  if (historialTipoFiltro === 'estandar') items = items.filter(r => r.Metodologia !== 'personalizado');
  if (historialTipoFiltro === 'personalizado') {
    items = items.filter(r => r.Metodologia === 'personalizado');
    if (historialTrabajoFiltro !== 'todos') items = items.filter(r => trabajoEstado(r) === historialTrabajoFiltro);
  }

  if (!items.length) {
    lista.innerHTML = '<p class="historial-empty">No hay registros en esta categoría.</p>';
    return;
  }

  lista.innerHTML = items.map(r => {
    const esPersonalizado = r.Metodologia === 'personalizado';
    const estado = esPersonalizado ? trabajoEstado(r) : (r.EstadoPago || 'pendiente');
    const info = esPersonalizado ? estadoTrabajoInfo(estado) : estadoPagoInfo(estado);
    const infoPagoPersonalizado = esPersonalizado ? pagoPersonalizadoInfo(r) : null;

    const btnE = puedeEliminar()
      ? `<button class="btn-eliminar" onclick="event.stopPropagation();eliminarRegistro('${r.firestoreId}')" title="Eliminar">✕</button>` : '';
    const btnEdit = puedeEditar()
      ? `<button class="btn-editar-hist" onclick="event.stopPropagation();abrirEditar('${r.firestoreId}')" title="Editar">✎</button>` : '';

    const itemsFactura = Array.isArray(r.Items) ? r.Items : [];
    const resumenItems = !esPersonalizado && itemsFactura.length > 1
      ? ` · ${itemsFactura.length} ítems en la factura`
      : '';

    return `
    <div class="historial-item clickable-row" onclick="abrirDetalle('${r.firestoreId}')">
      <div class="estado-barra" style="background:${info.color}"></div>
      ${r.AdjuntoURL && r.AdjuntoTipo && r.AdjuntoTipo.startsWith('image/')
        ? `<a href="${r.AdjuntoURL}" target="_blank" class="hist-thumb-wrap" onclick="event.stopPropagation()"><img src="${r.AdjuntoURL}" alt="adjunto" class="hist-thumb"></a>`
        : r.AdjuntoURL
          ? `<a href="${r.AdjuntoURL}" target="_blank" class="hist-thumb-wrap hist-thumb-pdf" onclick="event.stopPropagation()" title="${r.AdjuntoNombre || 'PDF'}">📄</a>` : ''}
      <div class="historial-info">
        <div class="historial-nombre">${r.Pieza} ${proyBadge(r)}${metBadge(r)}</div>
        <div class="historial-meta">${metaRegistro(r, false)}${resumenItems}</div>
      </div>
      <div style="display:flex;align-items:center;gap:10px;flex-shrink:0;">
        <div style="text-align:right;">
          <div class="historial-total">${formatearMonto(r.Moneda || 'ARS', r.Total)}</div>
          <div class="historial-fecha">${r.Fecha} ${r.Hora}</div>
          <div class="historial-estados-wrap">
            <span class="estado-pill" style="background:${info.bg};color:${info.color};">${info.label}</span>
            ${esPersonalizado ? `<span class="estado-pill" style="background:${infoPagoPersonalizado.bg};color:${infoPagoPersonalizado.color};">${infoPagoPersonalizado.label}${infoPagoPersonalizado.estado === 'anticipo' ? ' · ' + infoPagoPersonalizado.porcentaje + '%' : ''}</span>` : ''}
          </div>
        </div>
        ${btnEdit}${btnE}
      </div>
    </div>`;
  }).join('');
}

/* ════════════════════════════════════════════════════════
   PAGOS
   ════════════════════════════════════════════════════════ */
function renderPagos(filtro) {
  filtroActual = filtro;
  document.querySelectorAll('.filtro-btn').forEach(b =>
    b.classList.toggle('active', b.dataset.filtro === filtro)
  );
  const lista   = document.getElementById('pagosList');
  const resumen = document.getElementById('pagosResumen');
  if (!lista) return;

  // Suma por estado, separada por moneda (no se mezclan ARS/USD)
  const sumaPorMoneda = e => {
    const totales = {};
    inventario
      .filter(r => (r.EstadoPago || 'pendiente') === e)
      .forEach(r => {
        const m = r.Moneda || 'ARS';
        totales[m] = (totales[m] || 0) + parseFloat(r.Total || 0);
      });
    return totales;
  };

  const lineasMoneda = totales => {
    const monedas = Object.keys(totales);
    if (!monedas.length) return formatearMonto('ARS', 0);
    return monedas.map(m => formatearMonto(m, totales[m])).join(' · ');
  };

  if (resumen) {
    resumen.innerHTML = `
      <div class="resumen-card">
        <div class="resumen-label">Total</div>
        <div class="resumen-valor">${inventario.length}</div>
      </div>
      <div class="resumen-card" style="background:#fcebeb;border-color:#f09595;">
        <div class="resumen-label" style="color:#791f1f;">Pendiente</div>
        <div class="resumen-valor" style="color:#791f1f;font-size:15px;">${lineasMoneda(sumaPorMoneda('pendiente'))}</div>
      </div>
      <div class="resumen-card" style="background:#faeeda;border-color:#ef9f27;">
        <div class="resumen-label" style="color:#854f0b;">Habilitado</div>
        <div class="resumen-valor" style="color:#854f0b;font-size:15px;">${lineasMoneda(sumaPorMoneda('habilitado'))}</div>
      </div>
      <div class="resumen-card" style="background:#eaf3de;border-color:#97c459;">
        <div class="resumen-label" style="color:#27500a;">Pagado</div>
        <div class="resumen-valor" style="color:#27500a;font-size:15px;">${lineasMoneda(sumaPorMoneda('pagado'))}</div>
      </div>`;
  }

  let items = [...inventario].reverse();
  if (filtro === 'pendientes')  items = items.filter(r => (r.EstadoPago || 'pendiente') === 'pendiente');
  if (filtro === 'habilitados') items = items.filter(r => (r.EstadoPago || 'pendiente') === 'habilitado');
  if (filtro === 'pagados')     items = items.filter(r => (r.EstadoPago || 'pendiente') === 'pagado');

  if (!items.length) {
    lista.innerHTML = '<p class="pagos-empty">No hay registros en esta categoría.</p>';
    return;
  }

  lista.innerHTML = items.map(r => {
    const ep   = r.EstadoPago || 'pendiente';
    const info = estadoPagoInfo(ep);
    let acc = '';
    if (ep === 'pendiente'  && puedeHabilitar())    acc += `<button class="pago-toggle" onclick="event.stopPropagation();cambiarEstado('${r.firestoreId}','habilitado')" style="border-color:#ef9f27;color:#854f0b;">Habilitar</button>`;
    if (ep === 'habilitado' && puedeMarcarPagado())  acc += `<button class="pago-toggle" onclick="event.stopPropagation();cambiarEstado('${r.firestoreId}','pagado')" style="border-color:#639922;color:#27500a;">Marcar pagado</button>`;
    if (ep === 'pagado'     && puedeHabilitar())    acc += `<button class="pago-toggle" onclick="event.stopPropagation();cambiarEstado('${r.firestoreId}','habilitado')" style="border-color:#ef9f27;color:#854f0b;font-size:11px;">Revertir</button>`;
    const btnE = puedeEliminar()
      ? `<button class="btn-eliminar" onclick="event.stopPropagation();eliminarPago('${r.firestoreId}')">✕</button>`
      : '';
    return `
    <div class="pago-item clickable-row" style="border-left:4px solid ${info.color};padding-left:14px;" onclick="abrirDetalle('${r.firestoreId}')">
      ${r.AdjuntoURL && r.AdjuntoTipo && r.AdjuntoTipo.startsWith('image/')
        ? `<a href="${r.AdjuntoURL}" target="_blank" class="hist-thumb-wrap" onclick="event.stopPropagation()">
             <img src="${r.AdjuntoURL}" alt="adjunto" class="hist-thumb">
           </a>`
        : r.AdjuntoURL
          ? `<a href="${r.AdjuntoURL}" target="_blank" class="hist-thumb-wrap hist-thumb-pdf" onclick="event.stopPropagation()" title="${r.AdjuntoNombre || 'PDF'}">
               <svg xmlns="http://www.w3.org/2000/svg" width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="#c8420a" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round">
                 <path d="M14 2H6a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V8z"/>
                 <polyline points="14 2 14 8 20 8"/>
               </svg>
             </a>`
          : ''}
      <div class="pago-info">
        <div class="pago-nombre">${r.Pieza} ${proyBadge(r)}${metBadge(r)}</div>
        <div class="pago-meta">${metaRegistro(r, true)}</div>
      </div>
      <div class="pago-right">
        <div>
          <div class="pago-total">${formatearMonto(r.Moneda || 'ARS', r.Total)}</div>
          <span class="estado-pill" style="background:${info.bg};color:${info.color};">${info.label}</span>
        </div>
        ${acc}${btnE}
      </div>
    </div>`;
  }).join('');
}

async function cambiarPagoPersonalizado(firestoreId, nuevoEstado) {
  if (!puedeMarcarPagado()) return;
  const r = inventario.find(x => x.firestoreId === firestoreId);
  if (!r || r.Metodologia !== 'personalizado') return;
  if (nuevoEstado === 'pago_final') {
    await actualizarPagoPersonalizado(firestoreId, 'pago_final', 100);
    return;
  }
  if (nuevoEstado === 'anticipo') {
    const actual = pagoPersonalizadoInfo(r).porcentaje || 50;
    await actualizarPagoPersonalizado(firestoreId, 'anticipo', Math.min(99.9, Math.max(0.1, actual)));
    return;
  }
  await actualizarPagoPersonalizado(firestoreId, 'pendiente', 0);
}

async function cambiarPorcentajePago(firestoreId, valor) {
  if (!puedeMarcarPagado()) return;
  const pct = Math.min(99.9, Math.max(0.1, parseFloat(valor) || 0));
  await actualizarPagoPersonalizado(firestoreId, 'anticipo', pct);
}

async function actualizarPagoPersonalizado(firestoreId, estado, porcentaje) {
  const r = inventario.find(x => x.firestoreId === firestoreId);
  if (!r) return;
  const cambios = { EstadoPagoPersonalizado: estado, PorcentajePago: porcentaje };
  // Mantener EstadoPago por compatibilidad, sin usarlo como estado principal del personalizado.
  cambios.EstadoPago = estado === 'pago_final' ? 'pagado' : estado === 'anticipo' ? 'habilitado' : 'pendiente';
  try {
    await db.collection(COL).doc(firestoreId).update(cambios);
    Object.assign(r, cambios);
    renderModalVer(r);
  } catch (e) {
    alert('Error al actualizar el pago: ' + e.message);
  }
}

async function cambiarEstado(firestoreId, nuevoEstado) {
  if (nuevoEstado === 'habilitado' && !puedeHabilitar())    return;
  if (nuevoEstado === 'pagado'     && !puedeMarcarPagado()) return;
  const r = inventario.find(x => x.firestoreId === firestoreId);
  if (!r) return;
  if (nuevoEstado === 'pagado' && (r.EstadoPago || 'pendiente') !== 'habilitado') {
    alert('Solo se pueden pagar pedidos habilitados.');
    return;
  }
  try { await db.collection(COL).doc(firestoreId).update({ EstadoPago: nuevoEstado }); }
  catch (e) { alert('Error: ' + e.message); }
}

/* ════════════════════════════════════════════════════════
   ORDEN DE PAGO (manual, al aprobar el presupuesto)
   ════════════════════════════════════════════════════════ */
async function generarOrdenPago(firestoreId) {
  const r = inventario.find(x => x.firestoreId === firestoreId);
  if (!r) return;

  const ep = r.EstadoPago || 'pendiente';
  if (ep !== 'habilitado' && ep !== 'pagado') {
    alert('Solo se puede generar la Orden de Pago para pedidos habilitados o pagados.');
    return;
  }

  let nroOP = r.NroOP;
  if (!nroOP) {
    const ahora    = new Date();
    const prefijo  = `${ahora.getFullYear()}${String(ahora.getMonth() + 1).padStart(2, '0')}${String(ahora.getDate()).padStart(2, '0')}`;
    const delDia   = inventario.filter(x => x.NroOP && x.NroOP.startsWith(`OP ${prefijo}-`)).length;
    const nn       = String(delDia + 1).padStart(2, '0');
    nroOP = `OP ${prefijo}-${nn}`;

    // Persistir el N° OP (best-effort; ante error, igual se imprime)
    try {
      await db.collection(COL).doc(firestoreId).update({ NroOP: nroOP });
      const idx = inventario.findIndex(x => x.firestoreId === firestoreId);
      if (idx !== -1) inventario[idx].NroOP = nroOP;
      r.NroOP = nroOP;
    } catch (e) {
      console.warn('No se pudo persistir el N° OP:', e.message);
    }
  }

  const moneda            = r.Moneda || 'ARS';
  const totalTexto        = formatearMonto(moneda, r.Total);
  const letras             = montoEnLetras(r.Total);
  const fechaHoy           = new Date().toLocaleDateString('es-AR');
  const fechaHoraCompleta  = new Date().toLocaleString('es-AR');
  const nombresUsuario     = { guillermo: 'Guillermo', romero: 'Romero', admin: 'Administrador', oficina: 'Oficina' };
  const confeccionoNombre  = nombresUsuario[userActual] || userActual;
  const logoURL            = LOGO_ROMERO_PLANO;

  const esPersonalizado = r.Metodologia === 'personalizado';

  const sBody   = "font-family:Calibri,Arial,sans-serif;color:#1a1a1a;font-size:12.5px;line-height:1.5;margin:0;padding:24px 28px;";
  const sTd     = "padding:3px 6px 3px 0;font-size:12.5px;vertical-align:top;color:#1a1a1a;font-style:normal;text-decoration:none;";
  const sTdNum  = sTd + "text-align:right;white-space:nowrap;";
  const sTh     = "text-align:left;font-weight:400;border-bottom:1px solid #1a1a1a;padding:0 6px 6px 0;font-size:12.5px;color:#1a1a1a;text-decoration:none;";
  const sThNum  = sTh + "text-align:right;";

  const filasTabla = esPersonalizado
    ? (Array.isArray(r.Avances) && r.Avances.length
        ? r.Avances.map(a => `
      <tr>
        <td style="${sTd}">${r.Codigo || '—'}</td>
        <td style="${sTd}">${r.Pieza} — ${a.descripcion || 'Avance'}</td>
        <td style="${sTdNum}">1</td>
        <td style="${sTdNum}">${formatearMonto(moneda, a.monto)}</td>
        <td style="${sTdNum}">${formatearMonto(moneda, a.monto)}</td>
      </tr>`).join('')
        : `
      <tr>
        <td style="${sTd}">${r.Codigo || '—'}</td>
        <td style="${sTd}">${r.Pieza}</td>
        <td style="${sTdNum}">1</td>
        <td style="${sTdNum}">${totalTexto}</td>
        <td style="${sTdNum}">${totalTexto}</td>
      </tr>`)
    : (Array.isArray(r.Items) && r.Items.length
        ? r.Items.map(it => `
      <tr>
        <td style="${sTd}">${it.codigo || '—'}</td>
        <td style="${sTd}">${it.descripcion || '—'}${r.Proyecto ? ` (${r.Proyecto})` : ''}</td>
        <td style="${sTdNum}">${it.cantidad || 1}</td>
        <td style="${sTdNum}">${formatearMonto(moneda, it.precio || 0)}</td>
        <td style="${sTdNum}">${formatearMonto(moneda, it.total || 0)}</td>
      </tr>`).join('')
        : `
      <tr>
        <td style="${sTd}">${r.Codigo || '—'}</td>
        <td style="${sTd}">${r.Pieza}${r.Proyecto ? ` (${r.Proyecto})` : ''}</td>
        <td style="${sTdNum}">${r.Cantidad}</td>
        <td style="${sTdNum}">${formatearMonto(moneda, r.Precio_Unit || 0)}</td>
        <td style="${sTdNum}">${totalTexto}</td>
      </tr>`);


  const html = `<!DOCTYPE html>
<html lang="es"><head><meta charset="UTF-8">
<title>Orden de Pago ${nroOP}</title>
</head><body style="${sBody}">

  <div style="margin-bottom:10px;"><img src="${logoURL}" style="height:58px;object-fit:contain;" onerror="this.style.display='none'"></div>

  <div style="margin-top:4px;text-align:center;font-weight:700;font-size:16px;letter-spacing:.4px;color:#1a1a1a;">ORDEN DE COMPRA</div>
  <div style="text-align:center;font-size:12.5px;color:#1a1a1a;margin-top:4px;">
    <span style="font-weight:700;">N° ${nroOP}</span> · Brandsen, Pcia. de Buenos Aires, Argentina · ${fechaHoy}
  </div>

  <div style="margin-top:26px;">
    <div style="margin-bottom:4px;color:#1a1a1a;">Beneficiario:</div>
    <div style="font-style:italic;font-weight:700;color:#1a1a1a;">${(r.Proveedor || '—').toUpperCase()}</div>
    ${r.Factura ? `<div style="font-style:italic;font-weight:700;color:#1a1a1a;">Factura N° ${r.Factura}</div>` : ''}
  </div>

  <div style="margin-top:22px;">
    <div style="font-style:italic;color:#1a1a1a;">De mi mayor consideración:</div>
    <div style="font-style:italic;margin-top:4px;padding-left:34px;color:#1a1a1a;">Se aprueba el pago correspondiente al presupuesto habilitado, según el siguiente detalle:</div>
  </div>

  <table style="width:100%;border-collapse:collapse;margin-top:20px;">
    <thead>
      <tr>
        <th style="${sTh}">Código</th>
        <th style="${sTh}">Descripción</th>
        <th style="${sThNum}">Cant.</th>
        <th style="${sThNum}">Precio Unit.</th>
        <th style="${sThNum}">Importe</th>
      </tr>
    </thead>
    <tbody>${filasTabla}</tbody>
  </table>
  <div style="border-top:1px solid #444;margin-top:8px;"></div>

  <table style="border-collapse:collapse;margin-top:6px;margin-left:auto;">
    <tr><td style="padding:2px 0 2px 28px;font-weight:700;text-align:left;font-size:13.5px;color:#1a1a1a;">TOTAL</td><td style="padding:2px 0;font-weight:700;text-align:right;font-size:13.5px;color:#1a1a1a;white-space:nowrap;">${totalTexto}</td></tr>
  </table>

  <div style="margin-top:14px;font-style:italic;color:#1a1a1a;">${moneda === 'USD' ? 'Son dólares' : 'Son pesos'}: ${letras}.</div>

  ${r.Descripcion ? `<div style="margin-top:18px;color:#1a1a1a;"><span style="font-weight:700;">Observaciones:</span> ${r.Descripcion}</div>` : ''}

  <div style="margin-top:26px;color:#1a1a1a;">Sin otro particular, saludo Atte.,</div>

  <table style="width:78%;margin-left:auto;margin-right:auto;border-collapse:collapse;margin-top:70px;">
    <tr>
      <td style="width:33%;text-align:center;font-size:11.5px;color:#1a1a1a;padding:0 12px;">
        <div style="border-top:1px solid #444;margin-bottom:5px;padding-top:5px;font-weight:700;">Confeccionó</div>${confeccionoNombre}
      </td>
      <td style="width:33%;text-align:center;font-size:11.5px;color:#1a1a1a;padding:0 12px;">
        <div style="border-top:1px solid #444;margin-bottom:5px;padding-top:5px;font-weight:700;">Aprobó</div>&nbsp;
      </td>
      <td style="width:33%;text-align:center;font-size:11.5px;color:#1a1a1a;padding:0 12px;">
        <div style="border-top:1px solid #444;margin-bottom:5px;padding-top:5px;font-weight:700;">Recibí</div>&nbsp;
      </td>
    </tr>
  </table>

  <div style="margin-top:40px;text-align:center;font-size:10.5px;color:#c8860a;font-weight:600;">Av. Las Heras 3156 – Brandsen – Pcia. de Buenos Aires - Argentina</div>
  <div style="margin-top:4px;text-align:center;font-size:9px;color:#999;">Documento generado desde Gestión de Pagos MTTO — ${fechaHoraCompleta} · ${confeccionoNombre}</div>

  <script>window.onload = function () { window.print(); };<\/script>
</body></html>`;

  const ventana = window.open('', '_blank');
  if (!ventana) {
    alert('El navegador bloqueó la ventana emergente. Habilitá los pop-ups para generar la Orden de Pago.');
    return;
  }
  ventana.document.write(html);
  ventana.document.close();
}

/* ════════════════════════════════════════════════════════
   ÓRDENES DE COMPRA (cuestionario multi-producto)
   ════════════════════════════════════════════════════════ */
function agregarFilaOC(datos) {
  const body = document.getElementById('ocItemsBody');
  const id   = 'oc-fila-' + (++ocFilasCounter);
  const tr   = document.createElement('tr');
  tr.id = id;
  const ivaDefault = document.getElementById('ocIvaDefault').value || 21;
  tr.innerHTML = `
    <td><input type="text"   class="oc-codigo"    placeholder="Código"></td>
    <td class="oc-col-desc"><input type="text"   class="oc-desc"      placeholder="Descripción del producto"></td>
    <td class="oc-col-num"><input type="number" class="oc-cant"      value="1" min="1" step="1" oninput="recalcularOC()"></td>
    <td class="oc-col-money"><input type="number" class="oc-precio"    value="0" min="0" step="0.01" oninput="recalcularOC()"></td>
    <td class="oc-col-num"><input type="number" class="oc-ivapct"    value="${ivaDefault}" min="0" step="0.1" oninput="recalcularOC()"></td>
    <td class="oc-subtotal">$ 0,00</td>
    <td class="oc-total">$ 0,00</td>
    <td><button type="button" class="oc-btn-quitar-fila" onclick="quitarFilaOC('${id}')">✕</button></td>
  `;
  body.appendChild(tr);
  if (datos) {
    tr.querySelector('.oc-codigo').value = datos.codigo || '';
    tr.querySelector('.oc-desc').value   = datos.descripcion || '';
    tr.querySelector('.oc-cant').value   = datos.cantidad || 1;
    tr.querySelector('.oc-precio').value = datos.precio || 0;
    tr.querySelector('.oc-ivapct').value = datos.ivaPct != null ? datos.ivaPct : ivaDefault;
  }
  recalcularOC();
}

function quitarFilaOC(id) {
  const fila = document.getElementById(id);
  if (fila) fila.remove();
  if (!document.getElementById('ocItemsBody').children.length) agregarFilaOC();
  recalcularOC();
}

function leerFilasOC() {
  return [...document.querySelectorAll('#ocItemsBody tr')].map(tr => {
    const cantidad = parseFloat(tr.querySelector('.oc-cant').value) || 0;
    const precio   = parseFloat(tr.querySelector('.oc-precio').value) || 0;
    const ivaPct   = parseFloat(tr.querySelector('.oc-ivapct').value) || 0;
    const subtotal = cantidad * precio;
    const impuesto = subtotal * (ivaPct / 100);
    const total    = subtotal + impuesto;
    return {
      fila:        tr,
      codigo:      tr.querySelector('.oc-codigo').value.trim(),
      descripcion: tr.querySelector('.oc-desc').value.trim(),
      cantidad, precio, ivaPct, subtotal, impuesto, total
    };
  });
}

function recalcularOC() {
  const moneda = document.getElementById('ocMoneda').value;
  const items  = leerFilasOC();

  items.forEach(it => {
    it.fila.querySelector('.oc-subtotal').textContent = formatearMonto(moneda, it.subtotal);
    it.fila.querySelector('.oc-total').textContent     = formatearMonto(moneda, it.total);
  });

  const subtotalGral = items.reduce((a, it) => a + it.subtotal, 0);
  const ivaGral       = items.reduce((a, it) => a + it.impuesto, 0);
  const totalGral     = subtotalGral + ivaGral;

  document.getElementById('ocTotales').innerHTML = `
    <div class="oc-totales-fila"><span>Subtotal</span><span>${formatearMonto(moneda, subtotalGral)}</span></div>
    <div class="oc-totales-fila"><span>I.V.A.</span><span>${formatearMonto(moneda, ivaGral)}</span></div>
    <div class="oc-totales-fila oc-total-final"><span>TOTAL</span><span>${formatearMonto(moneda, totalGral)}</span></div>
  `;
}

async function generarNumeroOC() {
  const ahora   = new Date();
  const prefijo = `${ahora.getFullYear()}${String(ahora.getMonth() + 1).padStart(2, '0')}${String(ahora.getDate()).padStart(2, '0')}`;
  const delDia  = ordenesCompra.filter(x => x.NroOC && x.NroOC.startsWith(prefijo)).length;
  const nn      = String(delDia + 1).padStart(2, '0');
  return `${prefijo}${nn}`;
}

async function guardarYGenerarOC() {
  const proveedor  = document.getElementById('ocProveedor').value.trim();
  const cotizacion = document.getElementById('ocCotizacion').value.trim();
  const direccion  = document.getElementById('ocDireccion').value.trim();
  const localidad  = document.getElementById('ocLocalidad').value.trim();
  const moneda     = document.getElementById('ocMoneda').value;

  if (!proveedor) { alert('Ingresá el nombre del proveedor.'); return; }

  const items = leerFilasOC().filter(it => it.descripcion && it.cantidad > 0 && it.precio > 0);
  if (!items.length) { alert('Agregá al menos un producto con cantidad y precio válidos.'); return; }

  const subtotalGral = items.reduce((a, it) => a + it.subtotal, 0);
  const ivaGral       = items.reduce((a, it) => a + it.impuesto, 0);
  const totalGral     = subtotalGral + ivaGral;

  const ahora = new Date();
  const nroOC = await generarNumeroOC();

  const doc = {
    timestamp:  ahora.getTime(),
    Fecha:      ahora.toLocaleDateString('es-AR'),
    Usuario:    userActual,
    NroOC:      nroOC,
    Proveedor:  proveedor,
    Cotizacion: cotizacion,
    Direccion:  direccion,
    Localidad:  localidad,
    Moneda:     moneda,
    Items:      items.map(({ fila, ...resto }) => resto),
    Subtotal:   subtotalGral.toFixed(2),
    IVA:        ivaGral.toFixed(2),
    Total:      totalGral.toFixed(2)
  };

  mostrarToast('💾 Guardando Orden de Compra...', 'loading', 0);
  try {
    await db.collection(OC_COL).add(doc);
    mostrarToast('✅ Orden de Compra generada', 'success', 3000);
    imprimirOC(doc);

    // Reset del formulario
    ['ocProveedor', 'ocCotizacion', 'ocDireccion', 'ocLocalidad'].forEach(id => document.getElementById(id).value = '');
    document.getElementById('ocItemsBody').innerHTML = '';
    agregarFilaOC();
  } catch (e) {
    mostrarToast('❌ Error al guardar la Orden de Compra: ' + e.message, 'error', 5000);
  }
}

function renderOCList() {
  const cont = document.getElementById('ocList');
  if (!cont) return;
  const items = [...ordenesCompra].reverse();
  if (!items.length) {
    cont.innerHTML = '<p class="historial-empty">Todavía no se generaron órdenes de compra.</p>';
    return;
  }
  cont.innerHTML = items.map(o => `
    <div class="oc-list-item" onclick="verOC('${o.firestoreId}')">
      <div>
        <div class="oc-list-nro">N° ${o.NroOC} · ${o.Proveedor}</div>
        <div class="oc-list-meta">${o.Fecha} · ${(o.Items || []).length} producto(s)</div>
      </div>
      <div class="oc-list-total">${formatearMonto(o.Moneda || 'ARS', o.Total)}</div>
    </div>
  `).join('');
}

function verOC(firestoreId) {
  const o = ordenesCompra.find(x => x.firestoreId === firestoreId);
  if (o) imprimirOC(o);
}

function imprimirOC(o) {
  const moneda   = o.Moneda || 'ARS';
  const fechaFmt = o.Fecha || new Date().toLocaleDateString('es-AR');
  const items    = o.Items || [];

  // Estilos base reutilizados como strings (todo inline, sin <style>, para que se
  // vea igual sin importar el motor que renderice/convierta el HTML a PDF/imagen).
  const sBody   = "font-family:Calibri,Arial,sans-serif;color:#1a1a1a;font-size:12.5px;line-height:1.5;margin:0;padding:24px 28px;";
  const sTd     = "padding:3px 6px 3px 0;font-size:12.5px;vertical-align:top;color:#1a1a1a;font-style:normal;text-decoration:none;";
  const sTdNum  = sTd + "text-align:right;white-space:nowrap;";
  const sTh     = "text-align:left;font-weight:400;border-bottom:1px solid #1a1a1a;padding:0 6px 6px 0;font-size:12.5px;color:#1a1a1a;text-decoration:none;";
  const sThNum  = sTh + "text-align:right;";

  const filasTabla = items.map(it => `
      <tr>
        <td style="${sTd}">${it.codigo || '—'}</td>
        <td style="${sTd}">${it.descripcion}</td>
        <td style="${sTdNum}">${it.cantidad}</td>
        <td style="${sTdNum}">${formatearMonto(moneda, it.precio)}</td>
        <td style="${sTdNum}">${formatearMonto(moneda, it.subtotal)}</td>
        <td style="${sTdNum}">${formatearMonto(moneda, it.impuesto)}</td>
        <td style="${sTdNum}">${formatearMonto(moneda, it.total)}</td>
      </tr>`).join('');

  const html = `<!DOCTYPE html>
<html lang="es"><head><meta charset="UTF-8">
<title>Orden de Compra ${o.NroOC}</title>
</head><body style="${sBody}">

  <div style="margin-bottom:10px;"><img src="${LOGO_ROMERO_PLANO}" style="height:58px;object-fit:contain;" onerror="this.style.display='none'"></div>

  <div style="margin-top:4px;text-align:center;font-weight:700;font-size:16px;letter-spacing:.4px;color:#1a1a1a;">ORDEN DE COMPRA</div>
  <div style="text-align:center;font-size:12.5px;color:#1a1a1a;margin-top:4px;">
    <span style="font-weight:700;">N° ${o.NroOC}</span> · Brandsen, Pcia. de Buenos Aires, Argentina · ${fechaFmt}
  </div>

  <div style="margin-top:26px;">
    <div style="margin-bottom:4px;color:#1a1a1a;">Proveedor:</div>
    <div style="font-style:italic;font-weight:700;color:#1a1a1a;">${(o.Proveedor || '—').toUpperCase()}</div>
    ${o.Direccion ? `<div style="font-style:italic;font-weight:700;color:#1a1a1a;">${o.Direccion}</div>` : ''}
    ${o.Localidad ? `<div style="font-style:italic;font-weight:700;color:#1a1a1a;">${o.Localidad}</div>` : ''}
  </div>

  <div style="margin-top:22px;">
    <div style="font-style:italic;color:#1a1a1a;">De mi mayor consideración:</div>
    <div style="font-style:italic;margin-top:4px;padding-left:34px;color:#1a1a1a;">Por la presente aceptamos${o.Cotizacion ? ` la cotización # ${o.Cotizacion}` : ' la propuesta'} que se detalla a continuación:</div>
  </div>

  <table style="width:100%;border-collapse:collapse;margin-top:20px;">
    <thead>
      <tr>
        <th style="${sTh}">Código</th>
        <th style="${sTh}">Descripción</th>
        <th style="${sThNum}">Cantidad</th>
        <th style="${sThNum}">Precio</th>
        <th style="${sThNum}">Subtotal</th>
        <th style="${sThNum}">Impuesto</th>
        <th style="${sThNum}">Total</th>
      </tr>
    </thead>
    <tbody>${filasTabla}</tbody>
  </table>
  <div style="border-top:1px solid #444;margin-top:8px;"></div>

  <table style="border-collapse:collapse;margin-top:6px;margin-left:auto;">
    <tr><td style="padding:2px 0 2px 28px;font-weight:700;text-align:left;font-size:12.5px;color:#1a1a1a;">SUBTOTAL</td><td style="padding:2px 0;font-weight:700;text-align:right;font-size:12.5px;color:#1a1a1a;white-space:nowrap;">${formatearMonto(moneda, o.Subtotal)}</td></tr>
    <tr><td style="padding:2px 0 2px 28px;font-weight:700;text-align:left;font-size:12.5px;color:#1a1a1a;">I.V.A.</td><td style="padding:2px 0;font-weight:700;text-align:right;font-size:12.5px;color:#1a1a1a;white-space:nowrap;">${formatearMonto(moneda, o.IVA)}</td></tr>
    <tr><td style="padding:2px 0 2px 28px;font-weight:700;text-align:left;font-size:13.5px;color:#1a1a1a;">TOTAL</td><td style="padding:2px 0;font-weight:700;text-align:right;font-size:13.5px;color:#1a1a1a;white-space:nowrap;">${formatearMonto(moneda, o.Total)}</td></tr>
  </table>

  <div style="margin-top:26px;color:#1a1a1a;">Sin otro particular, saludo Atte.,</div>
  <div style="margin-top:40px;text-align:center;"><img src="${LOGO_ROMERO_FIRMA}" style="height:66px;object-fit:contain;display:block;margin:0 auto;" onerror="this.style.display='none'"></div>

  <div style="margin-top:40px;text-align:center;font-size:10.5px;color:#c8860a;font-weight:600;">Av. Las Heras 3156 – Brandsen – Pcia. de Buenos Aires - Argentina</div>
  <div style="margin-top:4px;text-align:center;font-size:9px;color:#999;">Documento generado desde Gestión de Pagos MTTO — ${new Date().toLocaleString('es-AR')}</div>

  <script>window.onload = function () { window.print(); };<\/script>
</body></html>`;

  const ventana = window.open('', '_blank');
  if (!ventana) {
    alert('El navegador bloqueó la ventana emergente. Habilitá los pop-ups para generar la Orden de Compra.');
    return;
  }
  ventana.document.write(html);
  ventana.document.close();
}

/* ════════════════════════════════════════════════════════
   GRÁFICA
   ════════════════════════════════════════════════════════ */
function initChart() {
  const ctx = document.getElementById('miGrafica');
  if (!ctx) return;
  if (miGrafica) miGrafica.destroy();
  miGrafica = new Chart(ctx.getContext('2d'), {
    type: 'line',
    data: {
      labels: inventario.map(d => d.Fecha + ' ' + d.Hora),
      datasets: [{
        label: 'Inversión ($)',
        data: inventario.map(d => parseFloat(d.Total)),
        borderColor: '#c8860a',
        backgroundColor: 'rgba(200,134,10,0.10)',
        pointBackgroundColor: '#c8420a',
        pointBorderColor: '#fff',
        pointBorderWidth: 2,
        pointRadius: 5,
        fill: true,
        tension: 0.4
      }]
    },
    options: {
      responsive: true,
      maintainAspectRatio: false,
      plugins: {
        legend: {
          labels: { color: '#7a4a20', font: { family: 'Nunito', weight: '700', size: 13 } }
        }
      },
      scales: {
        x: { ticks: { color: '#a07840', font: { family: 'Nunito', size: 11 } }, grid: { color: 'rgba(200,160,90,0.12)' } },
        y: { ticks: { color: '#a07840', font: { family: 'Nunito', size: 11 } }, grid: { color: 'rgba(200,160,90,0.12)' } }
      }
    }
  });
}

function actualizarComparador() {
  const grid = document.getElementById('statsGrid');
  if (!grid) return;
  grid.innerHTML = '';
  const tot = inventario.reduce((acc, r) => {
    acc[r.Mes] = (acc[r.Mes] || 0) + parseFloat(r.Total);
    return acc;
  }, {});
  for (const [mes, d] of Object.entries(tot)) {
    grid.innerHTML += `
      <div class="stat-card">
        <div class="stat-month">${mes}</div>
        <div class="stat-value">$${d.toLocaleString('es-AR', { maximumFractionDigits: 0 })}</div>
      </div>`;
  }
}

/* ════════════════════════════════════════════════════════
   EXCEL + LIMPIAR
   ════════════════════════════════════════════════════════ */
function exportarExcel() {
  if (!inventario.length) { alert('No hay registros para exportar.'); return; }
  const wb = XLSX.utils.book_new();
  [...new Set(inventario.map(r => r.Mes))].forEach(mes => {
    const datos = inventario
      .filter(r => r.Mes === mes)
      .map(({ firestoreId, timestamp, ...resto }) => resto);
    XLSX.utils.book_append_sheet(wb, XLSX.utils.json_to_sheet(datos), mes.toUpperCase());
  });
  XLSX.writeFile(wb, 'Inventario_RomeroPanificados.xlsx');
}

async function limpiarTodo() {
  if (!confirm('¿Borrar TODO el historial? Esta acción no se puede deshacer.')) return;
  try {
    const snap = await db.collection(COL).get();
    await Promise.all(snap.docs.map(d => d.ref.delete()));
    alert('Historial borrado.');
  } catch (e) {
    alert('Error: ' + e.message);
  }
} 

document.addEventListener('DOMContentLoaded', () => {
  if (document.getElementById('itemsFacturaList') && !document.querySelector('#itemsFacturaList .factura-item-row')) agregarItemFactura();
  toggleIVA();
});
